import{_ as t,a,o as r,a6 as o}from"./chunks/framework.CJDy2q7X.js";const u=JSON.parse(`{"title":"Get Shipping Methods","description":"","frontmatter":{"outline":false,"examples":[{"id":"get-shipping-methods","title":"Get Available Shipping Methods","description":"Retrieve available shipping methods for checkout.","request":"curl -X GET \\"http://localhost/api/shop/checkout-shipping-methods\\" \\\\\\n  -H \\"Accept: application/json\\" \\\\\\n  -H \\"X-STOREFRONT-KEY: pk_storefront_xxxxxxxxxxxxxxxxxxxxxxxxxxxxxxxx\\" \\\\\\n  -H \\"Authorization: Bearer 62f2b3f5-a455-4c78-93ba-eabca63d32ec\\"\\n","response":"HTTP/1.1 200 OK\\n\\n[\\n  {\\n    \\"id\\": \\"flatrate_flatrate_flatrate\\",\\n    \\"code\\": \\"flatrate\\",\\n    \\"label\\": \\"Flat Rate\\",\\n    \\"price\\": 10,\\n    \\"formattedPrice\\": \\"$10.00\\",\\n    \\"description\\": \\"Flat Rate Shipping\\",\\n    \\"method\\": \\"flatrate_flatrate\\",\\n    \\"methodTitle\\": \\"Flat Rate\\",\\n    \\"methodDescription\\": \\"Flat Rate Shipping\\",\\n    \\"basePrice\\": 10,\\n    \\"baseFormattedPrice\\": \\"$10.00\\",\\n    \\"carrier\\": \\"flatrate\\",\\n    \\"carrierTitle\\": \\"Flat Rate\\"\\n  },\\n  {\\n    \\"id\\": \\"free_free_free\\",\\n    \\"code\\": \\"free\\",\\n    \\"label\\": \\"Free Shipping\\",\\n    \\"price\\": 0,\\n    \\"formattedPrice\\": \\"$0.00\\",\\n    \\"description\\": \\"Free Shipping\\",\\n    \\"method\\": \\"free_free\\",\\n    \\"methodTitle\\": \\"Free Shipping\\",\\n    \\"methodDescription\\": \\"Free Shipping\\",\\n    \\"basePrice\\": 0,\\n    \\"baseFormattedPrice\\": \\"$0.00\\",\\n    \\"carrier\\": \\"free\\",\\n    \\"carrierTitle\\": \\"Free Shipping\\"\\n  }\\n]\\n","commonErrors":[{"error":"Empty array","cause":"No checkout address is saved on the cart yet, or no carrier serves the saved address","solution":"Save the address first with Set Checkout Address; an empty list is a 200, not an error"},{"error":"401 Unauthorized — Authentication token is required","cause":"No cart or customer token was sent as the Bearer token","solution":"Send the cartToken from Create Cart, or a logged-in customer's token"}]}]},"headers":[],"relativePath":"api/rest-api/shop/checkout/get-shipping-methods.md","filePath":"api/rest-api/shop/checkout/get-shipping-methods.md","lastUpdated":1787725411000}`),s={name:"api/rest-api/shop/checkout/get-shipping-methods.md"};function d(i,e,n,h,c,p){return r(),a("div",null,e[0]||(e[0]=[o('<h1 id="get-shipping-methods" tabindex="-1">Get Shipping Methods <a class="header-anchor" href="#get-shipping-methods" aria-label="Permalink to &quot;Get Shipping Methods&quot;">​</a></h1><p>Retrieve available shipping methods based on address and cart contents.</p><h2 id="endpoint" tabindex="-1">Endpoint <a class="header-anchor" href="#endpoint" aria-label="Permalink to &quot;Endpoint&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>GET /api/shop/checkout-shipping-methods</span></span></code></pre></div><p>Listing the rates is a <strong>GET with no body</strong>. The same path also accepts a <code>POST</code>, but that is the setter — see <a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a>. A <code>POST</code> sent here without a <code>shippingMethod</code> fails.</p><h2 id="request-headers" tabindex="-1">Request Headers <a class="header-anchor" href="#request-headers" aria-label="Permalink to &quot;Request Headers&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Header</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>Accept</code></td><td>Yes</td><td>application/json</td></tr><tr><td><code>X-STOREFRONT-KEY</code></td><td>Yes</td><td>Your storefront API key</td></tr><tr><td><code>Authorization</code></td><td>Yes</td><td>The cart&#39;s own token as a Bearer token, or a logged-in customer&#39;s token.</td></tr></tbody></table><p>The destination is taken from the address already saved on the cart. There is no way to quote rates for an arbitrary country, state, or postcode — those are not request parameters.</p><h2 id="response-fields-200-ok" tabindex="-1">Response Fields (200 OK) <a class="header-anchor" href="#response-fields-200-ok" aria-label="Permalink to &quot;Response Fields (200 OK)&quot;">​</a></h2><p>A bare array of rates.</p><table tabindex="0"><thead><tr><th>Field</th><th>Type</th><th>Description</th></tr></thead><tbody><tr><td><code>id</code></td><td>string</td><td>Rate identifier, e.g. <code>flatrate_flatrate_flatrate</code>.</td></tr><tr><td><code>method</code></td><td>string</td><td><strong>The value to send to <a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a></strong>, e.g. <code>flatrate_flatrate</code>. Note it differs from <code>id</code>.</td></tr><tr><td><code>code</code></td><td>string</td><td>Short carrier code.</td></tr><tr><td><code>label</code> / <code>methodTitle</code></td><td>string</td><td>Display name for the rate.</td></tr><tr><td><code>description</code> / <code>methodDescription</code></td><td>string</td><td>Description shown alongside it.</td></tr><tr><td><code>price</code> / <code>basePrice</code></td><td>number</td><td>Rate cost, in cart and base currency.</td></tr><tr><td><code>formattedPrice</code> / <code>baseFormattedPrice</code></td><td>string</td><td>The same amounts, currency-formatted.</td></tr><tr><td><code>carrier</code> / <code>carrierTitle</code></td><td>string</td><td>Carrier the rate belongs to.</td></tr></tbody></table><p>There is no delivery estimate — the payload carries no <code>estimatedDays</code> or delivery date.</p><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><ul><li><strong>Shipping step of checkout</strong> — call after the address is saved and render one radio option per rate, using <code>formattedPrice</code> for the label.</li><li><strong>Show &quot;free shipping&quot; when it qualifies</strong> — free-shipping rules surface as an ordinary rate with a <code>price</code> of <code>0</code>, so nothing special is needed to detect them.</li></ul><h2 id="best-practices" tabindex="-1">Best Practices <a class="header-anchor" href="#best-practices" aria-label="Permalink to &quot;Best Practices&quot;">​</a></h2><ul><li><strong>Save the address first</strong> — with none on the cart the response is <code>[]</code>, which reads as &quot;no carriers available&quot; rather than &quot;step out of order&quot;.</li><li><strong>Send <code>method</code>, not <code>id</code>, to the setter</strong> — the two look similar and the <code>id</code> value is rejected.</li><li><strong>Re-fetch after changing the address</strong> — rates depend on the destination and are not recalculated on the client.</li><li><strong>Treat an empty array as a blocked checkout</strong> — the order cannot be placed until a shipping method is set for a cart with shippable items.</li></ul><h2 id="related-resources" tabindex="-1">Related Resources <a class="header-anchor" href="#related-resources" aria-label="Permalink to &quot;Related Resources&quot;">​</a></h2><ul><li><a href="/api/rest-api/shop/checkout/set-shipping-method.html">Set Shipping Method</a> — save the chosen rate on the cart</li><li><a href="/api/rest-api/shop/checkout/get-payment-methods.html">Get Payment Methods</a> — the payment methods the store offers</li><li><a href="/api/rest-api/shop/checkout/get-addresses.html">Get Checkout Addresses</a> — read back the addresses saved on the cart</li></ul>',18)]))}const g=t(s,[["render",d]]);export{u as __pageData,g as default};
